<script>
const exportOptionAll = ['IsExportUrl', 'IsExportTitle', 'IsExportDescription', 'IsExportEmail', 'IsExportFacebook', 'IsExportLinkedin', 'IsExportTwitter', 'IsExportInstagram', 'IsFilter']
export default {
  name: 'task_export',
  data () {
    return {
      exportLoading: false,
      tableLoading: false,
      exportPath: '',
      exportType: {
        checkAll: false,
        type: [],
        IsExportSeparate: false
      },
      taskId: 0,
      page: {
        page: 1,
        num: 30,
        total: 0
      },
      isIndeterminateTable: false,
      isIndeterminate: false,
      table: [],
      exportOption: [
        {
          label: '网站',
          value: 'IsExportUrl'
        },
        {
          label: '标题',
          value: 'IsExportTitle'
        },
        {
          label: '说明',
          value: 'IsExportDescription'
        },
        {
          label: '邮箱',
          value: 'IsExportEmail'
        },
        {
          label: 'Facebook',
          value: 'IsExportFacebook'
        },
        {
          label: 'Linkedin',
          value: 'IsExportLinkedin'
        },
        {
          label: 'Twitter',
          value: 'IsExportTwitter'
        },
        {
          label: 'Instagram',
          value: 'IsExportInstagram'
        },
        {
          label: '过滤无数据网站',
          value: 'IsFilter'
        }
      ]
    }
  },
  methods: {
    init () {
      this.taskId = Number(this.$route.params.id)
      this.tableLoading = true
      this.SharpObj.getExportDataType(this.taskId, res => {
        res = JSON.parse(res)

        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        let index = res.Data.indexOf('IsExportSeparate')
        if (index !== -1) {
          this.exportType.IsExportSeparate = true
          res.Data.splice(index, 1)
        } else {
          this.exportType.IsExportSeparate = false
        }
        this.exportType.type = []
        this.exportType.type.push(...res.Data)
        this.handleExportChange(this.exportType.type)
      })
      this.SharpObj.getExportData(this.taskId, res => {
        this.table = []
        this.tableLoading = false
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.table = res.Data
        this.page.total = this.table.length
      })
    },
    changePage (page) {
      this.page.page = page
    },
    handleCheckAllChange (val) {
      this.exportType.type = val ? exportOptionAll : []
      this.isIndeterminate = false
    },
    handleExportChange (value) {
      let checkedCount = value.length
      this.exportType.checkAll = checkedCount === exportOptionAll.length
      this.isIndeterminate = checkedCount > 0 && checkedCount < exportOptionAll.length
    },
    checkAllTable () {
      this.isIndeterminateTable = false
    },
    handleTableChange (row) {
      let checkCount = 0
      for (let item of this.table) {
        item.IsCheck && checkCount++
      }
      if (checkCount > 0 && checkCount < this.table.length) {
        this.isIndeterminateTable = true
      } else {
        this.isIndeterminateTable = false
      }
    },
    handleSelectPath (e) {
      e.target.blur()
      this.SharpObj.getExportExcelPath(res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.exportPath = res.Data
      })
    },
    async doExport () {
      let validate = this.$WmlValidator.validate(this.exportPath, [
        {
          rule: 'isNonNull',
          errorMsg: '导出路径不能为空！'
        }])
      if (validate) {
        this.$WmlMsg(validate, 'warning')
        return
      }
      let confirm = await this.$WmlConfirm(`确认导出？`)
      if (!confirm) { return }
      this.exportLoading = true
      let exportData = []
      for (let item of this.table) {
        item.IsCheck && exportData.push(item)
      }
      let exportType = JSON.parse(JSON.stringify(this.exportType.type))
      this.exportType.IsExportSeparate && exportType.push('IsExportSeparate')
      this.SharpObj.exportExcel(JSON.stringify(exportData), this.exportPath, JSON.stringify(exportType), res => {
        this.exportLoading = false
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.$WmlMsg('导出成功！')
      })
    }
  },
  created () {
    this.init()
  },
  computed: {
    checkAll: {
      get: function () {
        if (this.table.length === 0) {
          return false
        }
        for (let item of this.table) {
          if (!item.IsCheck) {
            return false
          }
        }
        return true
      },
      set: function (bool) {
        for (let i = 0; i < this.table.length; i++) {
          this.$set(this.table[i], 'IsCheck', bool)
        }
      }
    },
    tableData: {
      get: function () {
        let newTableData = this.table.slice(this.page.num * (this.page.page - 1), this.page.num * this.page.page)
        return newTableData
      },
      set: function () { }
    }
  },
  watch: {
    '$route' () {
      this.init()
    }
  }
}
</script>

